#include "postquantiquecoin/core/Config.h"
#include <fstream>
namespace pqc { namespace { bool On(const std::string& v){ return v=="1"||v=="true"||v=="yes"; } } Result<NodeConfig> Config::Load(const std::filesystem::path& path){ NodeConfig c; std::ifstream in(path); if(!in) return Result<NodeConfig>::Ok(c); std::string line; while(std::getline(in,line)){ auto pos=line.find('='); if(pos==std::string::npos||line.empty()||line[0]=='#') continue; auto k=line.substr(0,pos), v=line.substr(pos+1); if(k=="network")c.network=v; else if(k=="datadir")c.datadir=v; else if(k=="port")c.port=static_cast<uint16_t>(std::stoul(v)); else if(k=="maxpeers")c.maxpeers=static_cast<uint32_t>(std::stoul(v)); else if(k=="listen")c.listen=On(v); else if(k=="seedpeer")c.seedpeer=v; else if(k=="mining_threads")c.mining_threads=static_cast<uint32_t>(std::stoul(v)); else if(k=="log_level")c.log_level=v; else if(k=="wallet_dir")c.wallet_dir=v; else if(k=="require_liboqs")c.require_liboqs=On(v); else if(k=="allow_dev_crypto")c.allow_dev_crypto=On(v); else if(k=="allow_legacy_pow")c.allow_legacy_pow=On(v); } return Result<NodeConfig>::Ok(c); } Result<void> Config::Save(const std::filesystem::path& path,const NodeConfig& c){ std::ofstream out(path); if(!out) return Result<void>::Err("config write failed"); out<<"network="<<c.network<<"\n"<<"datadir="<<c.datadir.string()<<"\n"<<"port="<<c.port<<"\n"<<"maxpeers="<<c.maxpeers<<"\n"<<"listen="<<(c.listen?1:0)<<"\n"<<"seedpeer="<<c.seedpeer<<"\n"<<"mining_threads="<<c.mining_threads<<"\n"<<"log_level="<<c.log_level<<"\n"<<"wallet_dir="<<c.wallet_dir.string()<<"\n"<<"require_liboqs="<<(c.require_liboqs?1:0)<<"\n"<<"allow_dev_crypto="<<(c.allow_dev_crypto?1:0)<<"\n"<<"allow_legacy_pow="<<(c.allow_legacy_pow?1:0)<<"\n"; return Result<void>::Ok(); } }
